import java.util.ArrayList;
import java.util.List;
import java.lang.reflect.Method;

/**
 * Invokes the real (private) Simulator.populate() in isolation, WITHOUT running
 * Simulator's view-building constructor, by allocating the instance via Unsafe
 * and reflectively setting the fields populate() needs. Then fingerprints the
 * species placed in each cell. Run against the baseline and refactored
 * Simulator: identical fingerprints => the populate() refactor is behaviour
 * preserving (uses the deterministic test Randomizer).
 */
public class PopDriver
{
    static final long FNV_OFFSET = -3750763034362895579L;
    static final long FNV_PRIME  = 1099511628211L;

    static long fnv(long h, long v)
    {
        for (int i = 0; i < 8; i++) { h ^= (v & 0xff); h *= FNV_PRIME; v >>>= 8; }
        return h;
    }

    static sun.misc.Unsafe unsafe() throws Exception
    {
        java.lang.reflect.Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
        f.setAccessible(true);
        return (sun.misc.Unsafe) f.get(null);
    }

    static void setField(Object o, String name, Object v) throws Exception
    {
        java.lang.reflect.Field f = Simulator.class.getDeclaredField(name);
        f.setAccessible(true);
        f.set(o, v);
    }

    static Object getField(Object o, String name) throws Exception
    {
        java.lang.reflect.Field f = Simulator.class.getDeclaredField(name);
        f.setAccessible(true);
        return f.get(o);
    }

    public static void main(String[] args) throws Exception
    {
        int depth = 60, width = 90;

        Simulator sim = (Simulator) unsafe().allocateInstance(Simulator.class);
        setField(sim, "field", new Field(depth, width));
        setField(sim, "animals", new ArrayList<LivingOrganism>());
        setField(sim, "plants", new ArrayList<LivingOrganism>());

        Method populate = Simulator.class.getDeclaredMethod("populate");
        populate.setAccessible(true);
        populate.invoke(sim);

        Field field = (Field) getField(sim, "field");
        long h = FNV_OFFSET;
        for (int r = 0; r < depth; r++) {
            for (int c = 0; c < width; c++) {
                Location loc = new Location(r, c);
                Object an = field.getObjectAt(loc, Animal.class);
                Object pl = field.getObjectAt(loc, Plant.class);
                long sig = 0;
                if (an != null) sig = an.getClass().getSimpleName().hashCode() & 0xffffffffL;
                if (pl != null) sig ^= 0x1000000L;
                h = fnv(h, sig);
            }
        }

        List<?> animals = (List<?>) getField(sim, "animals");
        List<?> plants = (List<?>) getField(sim, "plants");
        System.out.println("FP=" + h + " animals=" + animals.size() + " plants=" + plants.size());
    }
}

